    )
    parser.add_argument(
        '-o', '--output-dir',
        default='output',
        help='Output directory for generated files (default: output)'
    )
    parser.add_argument(
        '--terminal-only',
        action='store_true',
        help='Only output terminal alert, skip HTML generation'
    )
    parser.add_argument(
        '--html-only',
        action='store_true',
        help='Only generate HTML dashboard, skip terminal output'
    )

    args = parser.parse_args()

    # Load session report
    try:
        session_data = load_session_report(args.input_file)
