    # Generate outputs
    terminal_alert = generate_terminal_alert(stats, status_info)
    html_dashboard = generate_html_dashboard(stats, status_info, session_data)

    # Create output directory if needed
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    # Output terminal alert
    if not args.html_only:
        print(terminal_alert)

